import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"An ADR is a one-page decision record","description":"","frontmatter":{"title":"An ADR is a one-page decision record","type":"adr","date":"2026-10-28T00:00:00.000Z","updated":"2026-10-29T00:00:00.000Z","status":"accepted","applies_to":"`host` (`project/adrs`, `scripts/check-adrs.py`), all repos with `project/adrs`"},"headers":[],"relativePath":"handl/project/adrs/0161-adr-is-a-one-page-decision.md","filePath":"vendored/handl/project/adrs/0161-adr-is-a-one-page-decision.md"}'),a={name:`handl/project/adrs/0161-adr-is-a-one-page-decision.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0161-an-adr-is-a-one-page-decision-record" tabindex="-1">ADR-0161: An ADR is a one-page decision record <a class="header-anchor" href="#adr-0161-an-adr-is-a-one-page-decision-record" aria-label="Permalink to “ADR-0161: An ADR is a one-page decision record”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li>An ADR is <strong>at most ~8 KB and ten numbered rules</strong>. Algorithms, tables, crate trees, code shapes and phase plans go to <code>project/design/</code>, <code>project/TODO.md</code> or <code>project/tasks/</code> — never into an ADR.</li><li><code>## Why</code> is mandatory: the failure the decision prevents, in ≤8 lines. It is the memory of the mistake and is never trimmed.</li><li><code>## Not doing</code> is mandatory: each rejected alternative on one line with its cost. This is what stops a rejected design being re-proposed.</li><li><code>## Enforcement</code> is mandatory: the file or test where the decision is true in code, or <code>none — proposed</code>.</li><li>The status vocabulary is closed and lives in the frontmatter (ADR-0163): <code>proposed</code>, <code>accepted</code>, <code>implemented</code>, <code>landed</code>, <code>superseded</code>, <code>absorbed</code>, <code>rejected</code>, <code>unrecorded</code>. A successor is named by <code>superseded_by</code>; &quot;partially superseded&quot; is not a state — split the ADR instead.</li><li>A dead ADR keeps its <strong>number</strong> as a tombstone row (successor + one-line reason); its body is deleted. Numbers are never reused: code cites them.</li><li>Authority is single. When a decision replaces another, the replacement carries <code>Supersedes: ADR-N</code> in the same change, and there is exactly one design-of-record ADR per area.</li><li><code>project/DECISIONS.md</code> is generated from <code>## Decision</code> sections — one line per rule with its ADR link. It is the recall surface; the ADR is the argument behind it.</li><li><code>scripts/check-adrs.py</code> gates 1–7. Report-only for the legacy corpus; <code>--strict</code> for ADRs added or modified in a pull request.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The corpus is 189 ADRs / 1.9 MB and mostly unread: within <code>host</code>&#39;s 112, 56 are over 8 KB, 36 carry more than ten rules, 101 record no rejected alternative, and 109 do not name where they are enforced. The result is not a shortage of records but a failure to <em>re-read</em> them — the same kernel was specified five times with no supersession links (<code>0052</code> Implemented, <code>0103</code> &quot;the evaluator, not the calculus&quot;, <code>0106</code> &quot;design of record&quot;), and <code>0090</code> (direct CLI dispatch) still contradicts <code>0149</code> (no built-in tools). Each re-litigation costs a design session; each stale plan costs a reader an hour.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Leave ADRs as they are</strong> — measured cost: 47% of bytes are unimplemented proposals, and two accepted ADRs contradict each other unnoticed.</li><li><strong>Delete dead ADRs without tombstones</strong> — breaks 300+ citations in code (<code>0044</code> ×100, <code>0077</code> ×67, <code>0094</code> ×56).</li><li><strong>Move decisions to a wiki</strong> — drifts from the code it describes; ADR-0129 already keeps docs in the repo, on a <code>project</code> branch.</li><li><strong>Keep the design detail in the ADR &quot;just in case&quot;</strong> — it is already in <code>design/</code>, in the code, and in git history.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>The existing 53 oversized ADRs are grandfathered; they must satisfy this only when next edited, so no big-bang rewrite is needed.</li><li>Losing the plan from ADRs pushes scheduling into <code>TODO.md</code>/<code>tasks/</code>, which must stay honest — a cost accepted.</li><li>Compressing an implemented ADR no longer needs a supersession, because git keeps the history; only the decision text is normative.</li><li>Reviewers get a mechanical check instead of a style debate.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>host/scripts/check-adrs.py</code> (size, decision count, mandatory sections, supersession link, duplicate numbers).</li><li><code>automation/skills/write-adr/SKILL.md</code> — the authoring path points here.</li><li><code>host/project/adrs/TEMPLATE.md</code> — the skeleton.</li></ul><h2 id="revisit-if" tabindex="-1">Revisit if <a class="header-anchor" href="#revisit-if" aria-label="Permalink to “Revisit if”">​</a></h2><ul><li>The strict gate blocks a legitimately large decision — then split the ADR rather than raising the budget.</li></ul>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};